[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path ([IO.Path]::GetTempPath()) ('backup-roundtrip-'+[guid]::NewGuid().ToString('N'));$src=Join-Path $tmp 'source';$bak=Join-Path $tmp 'backup';$dst=Join-Path $tmp 'restored';try{New-Item -ItemType Directory -Force $src|Out-Null;New-Item -ItemType Directory -Force (Join-Path $src 'required-empty-directory')|Out-Null;Set-Content (Join-Path $src 'workspace.yaml') 'synthetic-workspace';Set-Content (Join-Path $src 'README.md') 'synthetic';powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Backup-Workspace.ps1') -Source $src -Destination $bak|Out-Null;powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Restore-Workspace.ps1') -Backup $bak -Destination $dst|Out-Null;if((Get-FileHash (Join-Path $src 'workspace.yaml')).Hash -ne (Get-FileHash (Join-Path $dst 'workspace.yaml')).Hash){throw 'ROUNDTRIP_HASH_MISMATCH'};if(-not(Test-Path (Join-Path $dst 'required-empty-directory') -PathType Container)){throw 'ROUNDTRIP_EMPTY_DIRECTORY_MISSING'};Write-Host 'PASS: Backup/restore roundtrip.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
